use ::std::num::NonZeroU64;
use ::std::result::Result;
struct PackedWord(u64); struct CodecError; enum KindCode { FixtureDirect, FixturePublicEscape, } struct TypedToken { family: KindCode, id: ::std::num::NonZeroU64 } enum Decoded { StopIteration, Token(TypedToken) } const TAG_PACKET:u64=6;
fn pack_bits(tag:u64,code:u64,id: ::std::num::NonZeroU64)->::std::result::Result<PackedWord,CodecError>{let tag_limit=1u64.checked_shl(16).ok_or(CodecError)?;let code_limit=1u64.checked_shl(16).ok_or(CodecError)?;let id_limit=1u64.checked_shl(31).ok_or(CodecError)?;if tag>=tag_limit||code>=code_limit||id.get()>=id_limit{return ::std::result::Result::Err(CodecError);}let tag_bits=tag.checked_shl(48).ok_or(CodecError)?;let code_bits=code.checked_shl(32).ok_or(CodecError)?;let id_bits=id.get().checked_shl(1).ok_or(CodecError)?;let first=tag_bits.checked_add(code_bits).ok_or(CodecError)?;::std::result::Result::Ok(PackedWord(first.checked_add(id_bits).ok_or(CodecError)?))}
fn unpack_bits(word:PackedWord)->::std::result::Result<(u64,u64),CodecError>{let tag=word.0.checked_shr(48).ok_or(CodecError)?;let tag_bits=tag.checked_shl(48).ok_or(CodecError)?;let payload=word.0.checked_sub(tag_bits).ok_or(CodecError)?;::std::result::Result::Ok((tag,payload))}
fn encode_token(kind:KindCode,id: ::std::num::NonZeroU64)->::std::result::Result<PackedWord,CodecError>{let code=match kind{KindCode::FixtureDirect=>1,KindCode::FixturePublicEscape=>2,};pack_bits(TAG_PACKET,code,id)}
fn decode_token(word:PackedWord)->::std::result::Result<Decoded,CodecError>{let(tag,raw_payload)=unpack_bits(word)?;if tag!=TAG_PACKET{return ::std::result::Result::Err(CodecError);}if raw_payload==0{return ::std::result::Result::Ok(Decoded::StopIteration);}if raw_payload!=0{if raw_payload&1!=0{return ::std::result::Result::Err(CodecError);}let code=raw_payload.checked_shr(32).ok_or(CodecError)?;let code_bits=code.checked_shl(32).ok_or(CodecError)?;let payload=raw_payload.checked_sub(code_bits).ok_or(CodecError)?;let raw_id=payload.checked_shr(1).ok_or(CodecError)?;let id=::std::num::NonZeroU64::new(raw_id).ok_or(CodecError)?;if id.get()==0{return ::std::result::Result::Err(CodecError);}if code==0{return ::std::result::Result::Err(CodecError);}let kind=match code{1=>KindCode::FixtureDirect,2=>KindCode::FixturePublicEscape,_=>{return ::std::result::Result::Err(CodecError);}};return ::std::result::Result::Ok(Decoded::Token(TypedToken{family:kind,id:id}));}::std::result::Result::Err(CodecError)}
fn emit_packet(kind:KindCode,id: ::std::num::NonZeroU64)->PackedWord{encode_token(kind,::std::num::NonZeroU64::new(9).unwrap()).unwrap()}
fn read_packet(word:PackedWord)->::std::result::Result<Decoded,CodecError>{decode_token(word)}
